package com.inventra.backend.service;
import com.inventra.backend.dto.*; import com.inventra.backend.model.User; import com.inventra.backend.repository.UserRepository; import com.inventra.backend.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.time.LocalDateTime;
@Service public class AuthService { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} public LoginResponse register(RegisterRequest r){if(users.existsByEmailIgnoreCase(r.getEmail()))throw new IllegalArgumentException("Email already registered");User u=new User();u.setName(r.getName());u.setEmail(r.getEmail().trim().toLowerCase());u.setPassword(encoder.encode(r.getPassword()));u.setActive(true);u.setCreatedAt(LocalDateTime.now());users.save(u);return new LoginResponse(jwt.generateToken(u.getEmail()),"Bearer",u.getId(),u.getName(),u.getEmail());} public LoginResponse login(LoginRequest r){User u=users.findByEmailIgnoreCase(r.getEmail()).orElseThrow(()->new IllegalArgumentException("Invalid email or password"));if(!u.isActive()||!encoder.matches(r.getPassword(),u.getPassword()))throw new IllegalArgumentException("Invalid email or password");return new LoginResponse(jwt.generateToken(u.getEmail()),"Bearer",u.getId(),u.getName(),u.getEmail());} public UserResponse getCurrentUser(String email){User u=users.findByEmailIgnoreCase(email).orElseThrow(()->new IllegalArgumentException("User not found"));return new UserResponse(u.getId(),u.getName(),u.getEmail(),u.isActive());} }
